import{_ as t,o,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 15 — Ship It","description":"","frontmatter":{"source":"weeks/15-ship-it/README.md"},"headers":[],"relativePath":"weeks/15-ship-it/index.md","filePath":"weeks/15-ship-it/index.md"}'),i={name:"weeks/15-ship-it/index.md"};function r(n,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="week-15--ship-it" tabindex="-1">Week 15 — Ship It <a class="header-anchor" href="#week-15--ship-it" aria-label="Permalink to &quot;Week 15 — Ship It&quot;">​</a></h1><blockquote><p>Done means deployed, documented and explainable, including honest about what doesn&#39;t work yet.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (30 min at most)</td><td>Read this page, skim the <a href="./polish-checklist.html">Polish checklist</a>, and check your production URL in a private window (<a href="#before-class">details</a>)</td></tr><tr><td><strong>Studio A</strong></td><td>Talk: done, polish, accessibility, known issues, where the field is going · polish sprint, including one fix by hand</td></tr><tr><td><strong>Studio B</strong></td><td>Known issues section · final security pass · rehearse your five-minute final presentation · post-course self-assessment (🔴 AI off, not graded)</td></tr><tr><td><strong>Due at the start of the final exam period</strong> (finals week has no Studio A)</td><td>The <a href="./homework.html">homework</a>: polish finished, documents up to date, presentation ready, final reflection with your revised AI-use rules on Canvas. The capstone is due at the same time (<a href="./../16-final-presentations/">week 16</a>)</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: polish fixes, finding accessibility problems, explaining check results, drafting README sections you then check · 🟡 AI limited: your Known issues section (you decide what&#39;s true; the AI may critique) · 🔴 AI off: one polish fix by hand, rehearsal feedback, the post-course self-assessment, the final reflection and your revised AI-use rules</td></tr><tr><td><strong>Must read</strong></td><td>README (this page), <a href="./lab.html">Week 15 lab — Polish, secure, record, rehearse</a>, <a href="./homework.html">Week 15 homework — Ready to ship</a>, the <a href="./polish-checklist.html">Polish checklist</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../resources/troubleshooting.html#deploying-to-vercel">Troubleshooting: Deploying to Vercel</a> · <a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a> · <a href="./../../resources/accessibility.html">Accessibility guide</a> · <a href="./../../templates/PROJECT_README.html">README template</a> · <a href="./../../projects/capstone.html#what-done-means">What &quot;done&quot; means</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your main user story works at the production URL, your README has an honest Known issues section, and your final reflection is on Canvas</td></tr><tr><td><strong>Time</strong></td><td>Studios 2.5 h · outside about 6 h (about 8.5 h in all)</td></tr></tbody></table><p>Canvas is the course&#39;s learning management system. Your self-assessment and final reflection go there, never in a repo.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>No exit ticket this week.</strong> University Regulation H-1-a says: &quot;No quizzes or exams may be given in lecture-recitation periods during the week before finals week.&quot; This week is for finishing.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Say what <strong>&quot;done&quot;</strong> means for a web app, and take a working demo to a shippable product.</li><li><strong>Polish</strong> an app: handle empty, loading and error states; work on a phone; set a page title and favicon; write a README a stranger can follow, with an honest <strong>Known issues</strong> section.</li><li>Apply <strong>accessibility basics</strong>: alt text, form labels, color contrast, keyboard use and visible focus.</li><li><strong>Tell the story</strong> of a project in a five-minute presentation: problem, demo, how you built it, what broke, what you learned; then answer a question about your code with the AI off.</li><li>Explain <strong>where the field is going</strong> (vibe coding to agentic engineering) without chasing every tool.</li><li>State the <strong>ethics and law</strong> basics: purely AI-generated output isn&#39;t copyrightable; disclose how you used AI.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><p>Before Studio A (30 minutes at most):</p><ul><li>☐ Read this page and skim the <a href="./polish-checklist.html">Polish checklist</a>.</li><li>☐ Open your <strong><a href="./../../resources/glossary.html#production-url">production URL</a></strong> (the main, permanent address of your deployed app) in a private window and check the main user story works. Run <code>npm test</code>.</li><li>☐ Open your Supabase project, if you have one, and restore it if it&#39;s paused. Free projects pause when nobody uses them (<a href="./../../TOOLS.html">Tool Handout</a>).</li><li>☐ Make sure <code>SECURITY_CHECKLIST.md</code> from week 14 is up to date; you&#39;ll do a final pass in Studio B.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-15.html" target="_blank" rel="noreferrer">slides</a>) · live demo of one polish fix · <a href="./lab.html#studio-a--polish-sprint-75-min">polish sprint</a>: the three states, phone, title and favicon, accessibility and the keyboard test · checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · <a href="./lab.html#studio-b--ready-to-ship-75-min">Known issues, final security pass, presentation rehearsal and the post-course self-assessment</a></td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-15.html" target="_blank" rel="noreferrer">Slides</a>: the 15-minute concept talk</li><li><a href="./lab.html">Lab</a>: Studio A and Studio B, with Core and If time parts</li><li><a href="./homework.html">Homework</a>: everything that must be ready by the final exam period</li><li><a href="./polish-checklist.html">Polish checklist</a>: a practical, tickable checklist</li><li><a href="./../16-final-presentations/">Week 16</a>: the five-minute presentation and the final submission checklist</li><li>Templates: <a href="./../../templates/PROJECT_README.html">README template</a>, <a href="./../../templates/SECURITY_CHECKLIST.html">SECURITY_CHECKLIST.md template</a>, <a href="./../../templates/TESTS.html">TESTS.md template</a>, and your capstone&#39;s <code>SPEC.md</code>, <code>AGENTS.md</code> and <code>PROMPTS.md</code></li></ul><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p><strong>Definition of done.</strong> A demo proves an idea; done means someone else can <em>use</em> it and <em>trust</em> it (<a href="./../../resources/glossary.html#definition-of-done">definition of done</a>). For this course, done = deployed at a production URL, documented so a stranger can run and understand it, tested (including edge cases), secure (the week 14 checklist), honest about its limits, and explainable by you.</p><p><strong>Polish is finishing the last 30%.</strong> People get most of the way fast, then stall on edge cases and production readiness: Osmani&#39;s &quot;70% problem&quot; (<a href="./../../research/landscape-report-2026-09.html">September report</a>). Polish is that last stretch. What does the app show when there&#39;s no data, while it&#39;s loading, or when something fails? Does it work on a phone? Does the browser tab say something better than &quot;Untitled&quot;? A Python habit to drop: an empty JavaScript array is truthy, so test <code>items.length === 0</code>, not <code>if (!items)</code>.</p><p><strong>Accessibility is part of done.</strong> <a href="./../../resources/glossary.html#accessibility">Accessibility</a> means people can use your app however they see, hear or move. Images need <a href="./../../resources/glossary.html#alt-text">alt text</a>; inputs need labels; text needs enough color contrast; everything clickable must work with the keyboard and show a visible focus outline. The <a href="./polish-checklist.html">Polish checklist</a> lists the checks.</p><p><strong>Known issues are a strength.</strong> Every real app ships with limits. Saying clearly what doesn&#39;t work, and what you&#39;d do about it, shows judgment. Michigan&#39;s agentic-engineering course judges its hackathon &quot;on evidence, not feature count&quot; (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/lectures/L08/slides.md" target="_blank" rel="noreferrer">EECS 498 slides</a>). In this course, naming a real limitation in your README&#39;s Known issues section <strong>never costs points</strong>.</p><p><strong>Tell the story.</strong> A good project talk is short and has a shape: the <strong>problem</strong>, a live <strong>demo</strong>, <strong>how</strong> you built it, <strong>what broke</strong> and how you recovered, and <strong>what you learned</strong>. &quot;What broke&quot; isn&#39;t a weakness to hide; it&#39;s the most convincing part.</p><p><strong>Where the field is going.</strong> Karpathy&#39;s framing: vibe coding lets anyone prototype; the professional version is <em><a href="./../../resources/glossary.html#agentic-engineering">agentic engineering</a></em>, and responsibility for security and understanding stays with the human (<a href="https://karpathy.bearblog.dev/sequoia-ascent-2026/" target="_blank" rel="noreferrer">Karpathy, 2026</a>). Tools churn; what lasts is the <strong>loop</strong>, a few open standards (<strong>AGENTS.md</strong>, <strong><a href="./../../resources/glossary.html#mcp">MCP</a></strong>, <strong>git</strong>), and knowing the difference between <em>rules</em> and <em>rails</em>. Rules are what you write for the agent, which it may ignore. Rails hold anyway: the Codespace, approval prompts, scoped tokens, spending caps and RLS (<a href="./../../research/landscape-update-2026-10.html">October update</a>). If you can say which rail protects each key, table and folder in your project, you&#39;ve learned something that outlasts every tool.</p><p><strong>Ethics and law, in brief.</strong> The US Copyright Office holds that <strong>purely AI-generated output is not copyrightable</strong>, and detailed prompts alone don&#39;t change that (<a href="https://www.copyright.gov/ai/Copyright-and-Artificial-Intelligence-Part-2-Copyrightability-Report.pdf" target="_blank" rel="noreferrer">USCO</a>). On <strong>16 September 2026</strong> the Ninth Circuit upheld dismissal of the DMCA claim in <strong>Doe v. GitHub</strong>; the open-source license claims remain before the district court (<a href="https://heathermeeker.com/2026/09/17/landmark-decision-in-doe-v-github-ai-court-battle/" target="_blank" rel="noreferrer">Heather Meeker</a>; <a href="https://www.courtlistener.com/docket/69495342/doe-et-al-v-github-inc-et-al/" target="_blank" rel="noreferrer">docket</a>).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Court cases move. As of 21 October 2026 no petition for rehearing had been reported. Re-check the status before you rely on it.</p></div><p><strong>Disclose.</strong> Keep <code>PROMPTS.md</code> honest, keep your <code>Assisted-by:</code> lines, and credit code, images or text you reused. About half of 281 open-source projects&#39; AI policies require disclosure (<a href="https://arxiv.org/abs/2609.07542" target="_blank" rel="noreferrer">Hora et al.</a>).</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>No exit ticket this week (see the note above). Check yourself instead, with the AI off; nobody collects your answers (the <a href="./../../resources/without-ai-skills.html#check-yourself">Check yourself</a> list on the six-skills page has more):</p><ul><li>Can you say in one sentence what your app does, for whom, and <strong>where authorization is enforced</strong> (or why it needs none)?</li><li>Can you use your whole app with the keyboard alone, and see where you are?</li><li>Pick one item in your Known issues section: can you explain why it happens and what you&#39;d do next?</li></ul><p>If any answer is &quot;not really&quot;, start your homework there. Your final reflection, part of this week&#39;s homework, compares how much you <em>felt</em> you understood with what you could actually explain.</p><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p><a href="./homework.html">Homework</a>: finish the polish checklist, bring every document up to date (README with Known issues, <code>SPEC.md</code>, <code>AGENTS.md</code>, <code>PROMPTS.md</code>, <code>TESTS.md</code>, <code>SECURITY_CHECKLIST.md</code>), get your presentation ready, and write the final reflection with your revised AI-use rules on Canvas. Due at the start of the final exam period. About 5.5 hours.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Vercel deploy fails:</strong> see <a href="./../../resources/troubleshooting.html#deploying-to-vercel">Troubleshooting: Deploying to Vercel</a>. Use a repo on your personal account, not an organization&#39;s. Fallbacks are in <a href="./../../TOOLS.html">Tool Handout</a>.</li><li><strong>Supabase project paused:</strong> restore it from the dashboard (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>), and again the day before the final presentations.</li><li><strong>Capstone still behind:</strong> ship the smallest honest version: one working feature, deployed, documented, with a Known issues section that says what&#39;s missing. A working small thing beats a broken big one. Tell your instructor before finals week.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Add one accessibility win beyond the checklist (a skip link, a reduced-motion option).</li><li>Write a short &quot;what I&#39;d build next&quot; note in your README.</li><li>Read ahead: <a href="./../16-final-presentations/">week 16</a> has the final submission checklist and a roadmap for after the course.</li></ul>',36)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
